insert into public.ar_reels_chapters(id,position,content) values('units',0,'{"id":"units","title":"Units & Measurements","subject":"Physics","subtitle":"The foundation of every discovery","symbol":"↗","color":"mint","available":true,"challengeId":"units-five-v1","version":1}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('units-1','units',18,'educational','{"id":"units-1","chapterId":"units","title":"The language of measurement","concept":"Every measurement needs a number and a unit.","equation":"Length → metre (m)","caption":"The SI base unit of length is the metre. A distance of 3 metres means three standard metre lengths.","duration":18,"diagram":"measure","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('units-2','units',18,'educational','{"id":"units-2","chapterId":"units","title":"Small scale, big precision","concept":"Convert centimetres into metres.","equation":"250 cm ÷ 100 = 2.5 m","caption":"One metre contains 100 centimetres. Divide a value in centimetres by 100 to express it in metres.","duration":18,"diagram":"measure","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('units-3','units',18,'educational','{"id":"units-3","chapterId":"units","title":"Speed has dimensions","concept":"Speed tells us distance travelled per unit time.","equation":"[speed] = L T⁻¹","caption":"Speed = distance / time. Its SI unit is metres per second and its dimensional formula is L T⁻¹.","duration":18,"diagram":"measure","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('units-4','units',18,'educational','{"id":"units-4","chapterId":"units","title":"Read between the marks","concept":"The least count is the smallest readable division.","equation":"1 cm ÷ 10 = 1 mm","caption":"A ruler with ten equal divisions per centimetre has a least count of 1 millimetre.","duration":18,"diagram":"measure","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('units-5','units',18,'educational','{"id":"units-5","chapterId":"units","title":"How certain is your answer?","concept":"Percentage error compares uncertainty with the measured value.","equation":"(0.1 ÷ 10) × 100 = 1%","caption":"For a length of 10 cm with uncertainty 0.1 cm, percentage error is 1%.","duration":18,"diagram":"measure","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_chapters(id,position,content) values('motion',1,'{"id":"motion","title":"Laws of Motion","subject":"Physics","subtitle":"Understand what moves the world","symbol":"→","color":"blue","available":true,"challengeId":"motion-five-v1","version":1}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('motion-1','motion',18,'educational','{"id":"motion-1","chapterId":"motion","title":"When nothing pushes","concept":"An object keeps its velocity when net force is zero.","equation":"ΣF = 0 → constant velocity","caption":"Newton’s first law: zero net force means no acceleration. A moving object continues at constant velocity.","duration":18,"diagram":"motion","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('motion-2','motion',18,'educational','{"id":"motion-2","chapterId":"motion","title":"Force changes motion","concept":"Acceleration grows with force and decreases with mass.","equation":"F = ma = 2 × 3 = 6 N","caption":"A 2 kg object accelerating at 3 m/s² needs a net force of 6 newtons.","duration":18,"diagram":"motion","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('motion-3','motion',18,'educational','{"id":"motion-3","chapterId":"motion","title":"Every action has a partner","concept":"Interaction forces act on different objects.","equation":"F₍A on B₎ = −F₍B on A₎","caption":"Newton’s third law pairs have equal magnitude and opposite directions, acting on different objects.","duration":18,"diagram":"motion","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('motion-4','motion',18,'educational','{"id":"motion-4","chapterId":"motion","title":"The measure of motion","concept":"Momentum depends on mass and velocity.","equation":"p = mv = 2 × 4 = 8 kg·m/s","caption":"A 2 kg object moving at 4 m/s has momentum 8 kg·m/s in the direction of its velocity.","duration":18,"diagram":"motion","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_media(id,chapter_id,duration,content_type,content) values('motion-5','motion',18,'educational','{"id":"motion-5","chapterId":"motion","title":"A push over time","concept":"Impulse equals the change in momentum.","equation":"J = FΔt = 3 × 2 = 6 N·s","caption":"A constant net force of 3 N acting for 2 seconds gives an impulse of 6 N·s.","duration":18,"diagram":"motion","contentType":"educational"}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_chapters(id,position,content) values('atoms',2,'{"id":"atoms","title":"Structure of Atom","subject":"Chemistry","subtitle":"A whole world within","symbol":"◎","color":"peach","available":false,"challengeId":"","version":1}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_chapters(id,position,content) values('cells',3,'{"id":"cells","title":"Cell: The Unit of Life","subject":"Biology","subtitle":"Life starts small","symbol":"◉","color":"green","available":false,"challengeId":"","version":1}'::jsonb) on conflict(id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-units-1','units-1','What is the SI base unit of length?','["Centimetre","Metre","Kilometre","Millimetre"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-units-1',1,'The metre is the SI base unit of length.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-units-2','units-2','250 cm is equal to how many metres?','["25 m","0.25 m","2.5 m","250 m"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-units-2',2,'Divide centimetres by 100: 250 / 100 = 2.5 m.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-units-3','units-3','What is the dimensional formula of speed?','["L T⁻¹","L T⁻²","M L T⁻¹","L² T⁻¹"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-units-3',0,'Speed = distance / time, so its dimensions are L T⁻¹.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-units-4','units-4','A ruler has 10 divisions in 1 cm. What is its least count?','["10 mm","1 cm","0.1 mm","1 mm"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-units-4',3,'1 cm / 10 = 0.1 cm = 1 mm.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-units-5','units-5','A 10 cm length has uncertainty 0.1 cm. What is its percentage error?','["10%","0.1%","1%","100%"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-units-5',2,'(0.1 / 10) × 100 = 1%.') on conflict(question_id) do nothing;
