insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-motion-1','motion-1','With zero net force, a moving object has…','["Constant velocity","Increasing speed","Zero velocity always","Increasing acceleration"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-motion-1',0,'Zero net force means zero acceleration, so velocity stays constant.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-motion-2','motion-2','What net force accelerates 2 kg at 3 m/s²?','["1.5 N","5 N","6 N","9 N"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-motion-2',2,'F = ma = 2 × 3 = 6 N.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-motion-3','motion-3','Action and reaction forces act on…','["The same object","Different objects","Only stationary objects","Only falling objects"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-motion-3',1,'Third-law pairs act on different interacting objects.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-motion-4','motion-4','What is the momentum of 2 kg moving at 4 m/s?','["2 kg·m/s","4 kg·m/s","6 kg·m/s","8 kg·m/s"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-motion-4',3,'p = mv = 2 × 4 = 8 kg·m/s.') on conflict(question_id) do nothing;
insert into public.ar_reels_questions(id,reel_id,prompt,options) values('q-motion-5','motion-5','A 3 N force acts for 2 s. What impulse does it give?','["6 N·s","1.5 N·s","5 N·s","9 N·s"]'::jsonb) on conflict(id) do nothing;
insert into ar_reels_private.answer_keys(question_id,correct_index,explanation) values('q-motion-5',0,'Impulse = FΔt = 3 × 2 = 6 N·s.') on conflict(question_id) do nothing;
